(function initFoodDemoBundles() {
  const ENDPOINT = "/.netlify/functions/admin-food-demo-bundles";
  const state = { relationship: null, bundles: [], active: null, steps: [], capabilities: {} };
  const page = location.pathname.split("/").pop() || "";
  function clean(v) { return String(v || "").trim(); }
  function esc(v) { return clean(v).replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])); }
  function token() { for (const key of ["maxwebstudioSupabaseAuthSession","mws_admin_supabase_session"]) { try { const value=JSON.parse(localStorage.getItem(key)||"null"); if(value?.access_token)return value.access_token;if(value?.accessToken)return value.accessToken; } catch {} } return ""; }
  function actionKey() { return window.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}-food-demo`; }
  async function api(method, payload, query="") { const auth=token(); if(!auth) throw new Error("Log opnieuw in om Food-demo’s te beheren."); const response=await fetch(`${ENDPOINT}${query}`,{method,headers:{Accept:"application/json",Authorization:`Bearer ${auth}`,...(payload?{"Content-Type":"application/json"}:{})},...(payload?{body:JSON.stringify(payload)}:{})}); const data=await response.json().catch(()=>({})); if(!response.ok||data.success===false) throw new Error(data.error||"De Food-demoactie kon niet worden uitgevoerd."); return data; }
  function status(v) { return ({not_sent:"Niet verzonden",ready:"Klaar",sent:"Verzonden",send_failed:"Verzending mislukt",revoked:"Ingetrokken",expired:"Verlopen"})[v]||v||"Onbekend"; }
  function formatDate(v) { if(!v)return "—"; try{return new Intl.DateTimeFormat("nl-NL",{dateStyle:"medium",timeStyle:"short"}).format(new Date(v));}catch{return "—";} }
  function relationQuery(r=state.relationship){if(!r)return "";return `?relationshipType=${encodeURIComponent(r.relationshipType)}&relationshipId=${encodeURIComponent(r.relationshipId)}`;}
  async function load(relationship=state.relationship) { state.relationship=relationship; const data=await api("GET",null,relationship?relationQuery(relationship):""); state.bundles=data.bundles||[]; state.steps=data.presentationSteps||[]; state.capabilities=data.capabilities||{}; renderEntry(); renderLibrary(); return data; }
  function ensureEntry() {
    if (!["admin-sales.html","admin-klanten.html"].includes(page) || document.getElementById("food-demo-entry")) return;
    const anchor = page === "admin-klanten.html" ? document.querySelector("[aria-label='Commerciele klantacties']") : document.querySelector("#leadfinder-list")?.previousElementSibling;
    if (!anchor) return;
    const box=document.createElement("section"); box.id="food-demo-entry"; box.className="food-demo-entry"; box.innerHTML='<div><span class="food-demo-badge">Food Factory</span><strong>Food-demonstratie</strong><p>Selecteer een lead of klant om beide demonstratielinks gecontroleerd te presenteren.</p></div><button class="button primary" type="button" data-food-demo-open disabled>Demo versturen</button>';
    anchor.parentNode.insertBefore(box, anchor.nextSibling);
    box.querySelector("button").addEventListener("click",()=>openForRelationship());
  }
  function renderEntry() { ensureEntry(); const box=document.getElementById("food-demo-entry"); if(!box)return; const button=box.querySelector("button"); const copy=box.querySelector("p"); button.disabled=!state.relationship; copy.textContent=state.relationship?`${state.relationship.companyName} · controlevenster zonder automatische verzending`:`Selecteer een lead of klant om beide demonstratielinks gecontroleerd te presenteren.`; }
  function ensureLibrary() {
    if(page!=="admin-demo-sites.html"||document.getElementById("food-demo-library"))return;
    const regular=document.getElementById("demo-sites-library"); if(!regular)return;
    const section=document.createElement("section"); section.id="food-demo-library";section.className="admin-section food-demo-library";section.innerHTML='<div class="admin-section-heading"><div><p class="section-kicker">Food Factory</p><h2>Food Demo Bundles</h2><p>Twee gecontroleerde routes: mobiele bestelomgeving en beveiligd restaurantdashboard.</p></div><span class="food-demo-badge">Testomgeving</span></div><div class="food-demo-library-grid" data-food-demo-list></div>';
    regular.parentNode.insertBefore(section,regular);
  }
  function renderLibrary(){ensureLibrary();const list=document.querySelector("[data-food-demo-list]");if(!list)return;list.innerHTML=state.bundles.length?state.bundles.map(card).join(""):'<div class="sales-timeline-empty">Geen Food Demo Bundles gevonden voor de huidige toegang.</div>';list.querySelectorAll("[data-food-demo-manage]").forEach(b=>b.addEventListener("click",()=>openBundle(b.dataset.foodDemoManage)));list.querySelectorAll("[data-food-demo-copy]").forEach(b=>b.addEventListener("click",()=>copyLinks(state.bundles.find(x=>x.id===b.dataset.foodDemoCopy))));}
  function card(b){return `<article class="food-demo-card"><div class="food-demo-card-head"><div><span>Food-demo</span><strong>${esc(b.displayName)}</strong><small>${esc(b.relationshipType)} · ${esc(b.relationshipId)}</small></div><img class="food-demo-card-qr" src="${esc(b.qrAssetUrl)}" alt="QR-code naar bestelomgeving"></div><div class="food-demo-card-body"><div class="food-demo-link-row"><span>Mobiel: ${esc(b.storefrontUrl)}</span><a class="button secondary" href="${esc(b.storefrontUrl)}" target="_blank" rel="noopener">Open</a></div><div class="food-demo-link-row"><span>Dashboard: veilige loginroute</span><a class="button secondary" href="${esc(b.dashboardDeeplink)}" target="_blank" rel="noopener">Open</a></div><div class="food-demo-status"><span>${esc(status(b.invitationStatus))}</span><span>Verzonden: ${esc(formatDate(b.lastSentAt))}</span>${b.revokedAt?`<span>Ingetrokken: ${esc(formatDate(b.revokedAt))}</span>`:""}</div><div class="food-demo-actions"><button class="button primary" type="button" data-food-demo-manage="${esc(b.id)}">Presenteren / versturen</button><button class="button secondary" type="button" data-food-demo-copy="${esc(b.id)}">Links kopiëren</button></div></div></article>`;}
  async function openForRelationship(factoryProjectId=""){if(!state.relationship)return;let bundle=state.bundles.find(b=>factoryProjectId?b.factoryProjectId===factoryProjectId:b.relationshipId===state.relationship.relationshipId);if(!bundle){const data=await api("POST",{action:"create",relationshipType:state.relationship.relationshipType,relationshipId:state.relationship.relationshipId,factoryProjectId,displayName:state.relationship.companyName,blueprintKey:"silverado-food-v1"});bundle={...data.bundle,mailPreview:data.mailPreview};state.bundles=[bundle,...state.bundles];renderLibrary();}openModal(bundle);}
  function openBundle(id){const bundle=state.bundles.find(b=>b.id===id);if(bundle)openModal(bundle);}
  function ensureModal(){let root=document.getElementById("food-demo-modal");if(root)return root;root=document.createElement("div");root.id="food-demo-modal";root.className="food-demo-modal";root.hidden=true;root.innerHTML='<section class="food-demo-dialog" role="dialog" aria-modal="true" aria-labelledby="food-demo-title"><header><div><span class="food-demo-badge">Food-demo · testomgeving</span><h2 id="food-demo-title">Demonstratie controleren</h2></div><button class="food-demo-close" type="button" aria-label="Sluiten">×</button></header><div class="food-demo-dialog-body" data-food-demo-body></div><footer class="food-demo-dialog-actions"><button class="button secondary" type="button" data-action="copy">Links kopiëren</button><button class="button secondary" type="button" data-action="check">Links controleren</button><button class="button secondary" type="button" data-action="test">Testmail versturen</button><button class="button secondary danger" type="button" data-action="revoke">Uitnodiging intrekken</button><button class="button secondary" type="button" data-action="resend">Opnieuw versturen</button><button class="button primary" type="button" data-action="send">Demo versturen</button></footer></section>';
    document.body.append(root);root.querySelector(".food-demo-close").addEventListener("click",closeModal);root.addEventListener("click",e=>{if(e.target===root)closeModal();});root.querySelectorAll("[data-action]").forEach(button=>button.addEventListener("click",()=>perform(button.dataset.action,button)));return root;}
  function openModal(bundle){state.active=bundle;const root=ensureModal();root.hidden=false;document.body.classList.add("admin-modal-open");renderModal();}
  function closeModal(){const root=document.getElementById("food-demo-modal");if(root)root.hidden=true;document.body.classList.remove("admin-modal-open");}
  function renderModal(){const b=state.active,body=document.querySelector("[data-food-demo-body]");if(!b||!body)return;const mail=b.mailPreview||{};body.innerHTML=`<section class="food-demo-overview"><img src="${esc(b.qrAssetUrl)}" alt="QR-code naar exact de mobiele bestelomgeving"><dl><dt>Naam</dt><dd><strong>${esc(b.displayName)}</strong></dd><dt>Type demo</dt><dd>Food</dd><dt>Mobiele omgeving</dt><dd><a href="${esc(b.storefrontUrl)}" target="_blank" rel="noopener">${esc(b.storefrontUrl)}</a></dd><dt>Restaurantdashboard</dt><dd><a href="${esc(b.dashboardDeeplink)}" target="_blank" rel="noopener">Veilig openen via login</a></dd><dt>Uitnodiging</dt><dd>${esc(status(b.invitationStatus))}</dd><dt>Ontvanger</dt><dd>${esc(b.recipientEmail||"Nog geen geldig relatieadres")}</dd><dt>Bereikbaarheid</dt><dd>Storefront: ${esc(b.storefrontStatus)} · dashboard: ${esc(b.dashboardStatus)}</dd></dl></section><section class="food-demo-presentation"><h3>Presentatiemodus</h3><div class="food-demo-actions"><a class="button primary" href="${esc(b.storefrontUrl)}" target="_blank" rel="noopener">Open bestelomgeving</a><a class="button secondary" href="${esc(b.dashboardDeeplink)}" target="_blank" rel="noopener">Open restaurantdashboard</a></div><ol>${state.steps.map((s,i)=>`<li${i===3?' data-unavailable title="Bezorgen is niet beschikbaar; uitsluitend afhalen"':''}>${esc(s)}</li>`).join("")}</ol></section><section class="food-demo-email-preview"><h3>E-mailvoorbeeld</h3><p><strong>Onderwerp:</strong> ${esc(mail.subject||"Preview wordt server-side geladen")}</p>${mail.html?`<iframe title="E-mailvoorbeeld" sandbox srcdoc="${esc(mail.html)}"></iframe>`:`<p>Heropen dit venster nadat de bundle is geladen om het volledige voorbeeld te zien.</p>`}</section><p class="food-demo-message" data-food-demo-message>Het openen van dit venster verstuurt niets.</p>`;const revoked=Boolean(b.revokedAt);document.querySelector('[data-action="revoke"]').disabled=revoked;document.querySelector('[data-action="resend"]').disabled=(!revoked&&b.invitationStatus!=="sent"&&b.invitationStatus!=="send_failed")||!state.capabilities.canLiveSend;document.querySelector('[data-action="send"]').disabled=!state.capabilities.canLiveSend;document.querySelector('[data-action="test"]').disabled=!state.capabilities.canTestMail;}
  async function perform(action,button){if(!state.active)return;const msg=document.querySelector("[data-food-demo-message]");button.disabled=true;try{if(action==="copy"){await copyLinks(state.active);setMessage(msg,"Beide links zijn gekopieerd.","success");return;}const serverAction=action==="check"?"check_links":action;const data=await api("POST",{action:serverAction,bundleId:state.active.id,actionKey:actionKey()});if(data.bundle){state.active={...state.active,...data.bundle};state.bundles=state.bundles.map(b=>b.id===data.bundle.id?{...b,...data.bundle}:b);}setMessage(msg,data.message||"Actie veilig verwerkt.","success");renderLibrary();renderModal();}catch(error){setMessage(msg,error.message,"error");}finally{button.disabled=false;}}
  async function copyLinks(b){if(!b)return;await navigator.clipboard.writeText(`Bestelomgeving: ${b.storefrontUrl}\nRestaurantdashboard: ${b.dashboardDeeplink}`);}
  function setMessage(node,text,tone){if(!node)return;node.textContent=text;node.className=`food-demo-message ${tone||""}`;}
  async function boot(){ensureEntry();ensureLibrary();if(!window.ActiveRelationship)return;const relationship=await window.ActiveRelationship.whenReady();try{await load(relationship);const query=new URLSearchParams(location.search);if(page==="admin-demo-sites.html"&&query.get("openFoodDemo")==="1")await openForRelationship(clean(query.get("factoryProjectId")));}catch(error){renderEntry();const list=document.querySelector("[data-food-demo-list]");if(list)list.innerHTML=`<div class="sales-timeline-empty">${esc(error.message)}</div>`;}window.ActiveRelationship.subscribeToRelationshipChanges(r=>load(r).catch(()=>{}));}
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",boot,{once:true});else boot();
})();
